{"path":"src/lib/time.ts","content":"export type TimeFormat = '12h' | '24h'
export type Mode = 'meeting' | 'base'
export type CellState = 'sleep' | 'awake' | 'overlap'

/** UTC offset in minutes for a zone at the current instant (DST handled by Intl). */
export function getOffsetMinutes(timeZone: string, date = new Date()): number {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date)
  const v: Record<string, number> = {}
  for (const p of parts) if (p.type !== 'literal') v[p.type] = Number(p.value)
  const asUTC = Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second)
  const truncated = Math.floor(date.getTime() / 1000) * 1000
  return Math.round((asUTC - truncated) / 60000)
}

export function formatOffset(minutes: number): string {
  const sign = minutes < 0 ? '-' : '+'
  const abs = Math.abs(minutes)
  const h = Math.floor(abs / 60)
  const m = abs % 60
  return m === 0 ? `UTC${sign}${h}` : `UTC${sign}${h}:${String(m).padStart(2, '0')}`
}

/** Format a wall-clock time in minutes-from-midnight (may be 1440 for exclusive end). */
export function formatMinutes(totalMinutes: number, format: TimeFormat): string {
  const norm = ((totalMinutes % 1440) + 1440) % 1440
  const h24 = Math.floor(norm / 60)
  const m = norm % 60
  if (format === '24h') {
    return `${String(h24).padStart(2, '0')}:${String(m).padStart(2, '0')}`
  }
  const suffix = h24 < 12 ? 'am' : 'pm'
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12
  return m === 0 ? `${h12}${suffix}` : `${h12}:${String(m).padStart(2, '0')}${suffix}`
}

export function formatHour(hour: number, format: TimeFormat): string {
  return formatMinutes(hour * 60, format)
}

/** Compact label for a grid cell. Keeps :30 / :45 visible for fractional offsets. */
export function formatCell(totalMinutes: number, format: TimeFormat): string {
  const norm = ((totalMinutes % 1440) + 1440) % 1440
  const h24 = Math.floor(norm / 60)
  const m = norm % 60
  if (format === '24h') {
    return m === 0 ? String(h24).padStart(2, '0') : `${String(h24).padStart(2, '0')}:${String(m).padStart(2, '0')}`
  }
  const suffix = h24 < 12 ? 'a' : 'p'
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12
  return m === 0 ? `${h12}${suffix}` : `${h12}:${String(m).padStart(2, '0')}${suffix}`
}

export function isAwakeAt(localMinutes: number, wake: number, sleep: number): boolean {
  const norm = ((localMinutes % 1440) + 1440) % 1440
  const wakeMin = wake * 60
  const sleepMin = sleep * 60
  if (wakeMin === sleepMin) return true // degenerate 24h window
  if (wakeMin < sleepMin) return norm >= wakeMin && norm < sleepMin
  // overnight window, e.g. wake 22 -> sleep 6
  return norm >= wakeMin || norm < sleepMin
}

/** Group sorted reference-hours (0-23) into contiguous inclusive-start / exclusive-end ranges. */
export function groupRanges(hours: number[]): Array<{ start: number; end: number }> {
  const ranges: Array<{ start: number; end: number }> = []
  for (const h of hours) {
    const last = ranges[ranges.length - 1]
    if (last && h === last.end) last.end = h + 1
    else ranges.push({ start: h, end: h + 1 })
  }
  return ranges
}

export function formatRange(r: { start: number; end: number }, format: TimeFormat): string {
  return `${formatHour(r.start, format)} — ${formatHour(r.end % 24, format)}`
}
"}

{"path":"src/App.tsx","content":"import { useEffect, useMemo, useRef, useState } from 'react'
import { CITY_CATALOG, DEFAULT_CITY_IDS, cityById, type City } from './data/cities'
import {
  formatCell, formatHour, formatOffset, formatRange, getOffsetMinutes, groupRanges, isAwakeAt,
  type CellState, type Mode, type TimeFormat,
} from './lib/time'

const STORAGE_KEY = 'timezone-overlap-v1'
const HOURS = Array.from({ length: 24 }, (_, i) => i)

type Persisted = { cityIds: string[]; mode: Mode; wake: number; sleep: number; format: TimeFormat }

function loadPersisted(): Persisted {
  const fallback: Persisted = { cityIds: DEFAULT_CITY_IDS, mode: 'meeting', wake: 7, sleep: 23, format: '12h' }
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return fallback
    const parsed = JSON.parse(raw) as Partial<Persisted>
    const cityIds = Array.isArray(parsed.cityIds)
      ? [...new Set(parsed.cityIds.filter((id) => cityById.has(id)))]
      : fallback.cityIds
    return {
      cityIds: cityIds.length ? cityIds : fallback.cityIds,
      mode: parsed.mode === 'base' ? 'base' : 'meeting',
      wake: Number.isInteger(parsed.wake) && parsed.wake! >= 0 && parsed.wake! <= 23 ? parsed.wake! : 7,
      sleep: Number.isInteger(parsed.sleep) && parsed.sleep! >= 0 && parsed.sleep! <= 23 ? parsed.sleep! : 23,
      format: parsed.format === '24h' ? '24h' : '12h',
    }
  } catch {
    return fallback
  }
}

export default function App() {
  const [initial] = useState(loadPersisted)
  const [cityIds, setCityIds] = useState<string[]>(initial.cityIds)
  const [mode, setMode] = useState<Mode>(initial.mode)
  const [wake, setWake] = useState(initial.wake)
  const [sleep, setSleep] = useState(initial.sleep)
  const [format, setFormat] = useState<TimeFormat>(initial.format)
  const [query, setQuery] = useState('')
  const [pickerOpen, setPickerOpen] = useState(false)
  const pickerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ cityIds, mode, wake, sleep, format } satisfies Persisted))
  }, [cityIds, mode, wake, sleep, format])

  useEffect(() => {
    const onDoc = (e: MouseEvent) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target as Node)) setPickerOpen(false)
    }
    document.addEventListener('mousedown', onDoc)
    return () => document.removeEventListener('mousedown', onDoc)
  }, [])

  const cities = useMemo(
    () => cityIds.map((id) => cityById.get(id)!).filter(Boolean),
    [cityIds],
  )
  const reference: City | undefined = cities[0]

  const offsets = useMemo(() => {
    const map = new Map<string, number>()
    for (const c of cities) map.set(c.id, getOffsetMinutes(c.timeZone))
    return map
  }, [cities])

  const refOffset = reference ? (offsets.get(reference.id) ?? 0) : 0

  // awake[cityId][refHour] and localMinutes[cityId][refHour]
  const { awake, localMinutes } = useMemo(() => {
    const awakeMap = new Map<string, boolean[]>()
    const localMap = new Map<string, number[]>()
    for (const c of cities) {
      const diff = (offsets.get(c.id) ?? 0) - refOffset
      const locals = HOURS.map((h) => h * 60 + diff)
      localMap.set(c.id, locals)
      awakeMap.set(c.id, locals.map((m) => isAwakeAt(m, wake, sleep)))
    }
    return { awake: awakeMap, localMinutes: localMap }
  }, [cities, offsets, refOffset, wake, sleep])

  const meetingOverlap = useMemo(
    () => (cities.length ? HOURS.filter((h) => cities.every((c) => awake.get(c.id)?.[h])) : []),
    [cities, awake],
  )

  const baseOverlap = useMemo(() => {
    const map = new Map<string, number[]>()
    if (!reference) return map
    const refAwake = awake.get(reference.id) ?? []
    for (const c of cities.slice(1)) {
      map.set(c.id, HOURS.filter((h) => refAwake[h] && awake.get(c.id)?.[h]))
    }
    return map
  }, [cities, awake, reference])

  function cellState(city: City, h: number): CellState {
    if (!awake.get(city.id)?.[h]) return 'sleep'
    if (mode === 'meeting') return meetingOverlap.includes(h) ? 'overlap' : 'awake'
    if (city.id === reference?.id) return 'awake'
    return baseOverlap.get(city.id)?.includes(h) ? 'overlap' : 'awake'
  }

  const available = useMemo(() => {
    const q = query.trim().toLowerCase()
    return CITY_CATALOG.filter((c) => !cityIds.includes(c.id))
      .filter((c) => !q || c.name.toLowerCase().includes(q) || c.country.toLowerCase().includes(q) || c.region.toLowerCase().includes(q))
  }, [query, cityIds])

  const addCity = (id: string) => {
    setCityIds((prev) => (prev.includes(id) ? prev : [...prev, id]))
    setQuery('')
    setPickerOpen(false)
  }
  const removeCity = (id: string) => setCityIds((prev) => prev.filter((c) => c !== id))
  const promote = (id: string) => setCityIds((prev) => [id, ...prev.filter((c) => c !== id)])

  const meetingRanges = groupRanges(meetingOverlap)

  return (
    <div className="page">
      <header className="header">
        <div>
          <h1>muse-wonder-full-1.0</h1>
          <p className="subtitle">Timezone overlap checker — find the hours when everyone is awake.</p>
        </div>
        <div className="mode-toggle" role="group" aria-label="Mode">
          <button
            type="button"
            className={mode === 'meeting' ? 'mode-btn active' : 'mode-btn'}
            aria-pressed={mode === 'meeting'}
            onClick={() => setMode('meeting')}
          >
            Meeting Mode
          </button>
          <button
            type="button"
            className={mode === 'base' ? 'mode-btn active' : 'mode-btn'}
            aria-pressed={mode === 'base'}
            onClick={() => setMode('base')}
          >
            Base Mode
          </button>
        </div>
      </header>

      <p className="mode-help">
        {mode === 'meeting'
          ? 'Meeting Mode: one shared window where every selected city is awake at the same time.'
          : `Base Mode: each city is compared independently against ${reference ? reference.name : 'the reference city'}.`}
      </p>

      <section className="controls" aria-label="Controls">
        <div className="picker" ref={pickerRef}>
          <label htmlFor="city-search">Add a city</label>
          <input
            id="city-search"
            type="text"
            placeholder="Search by city or country…"
            aria-label="Search cities"
            value={query}
            onFocus={() => setPickerOpen(true)}
            onChange={(e) => { setQuery(e.target.value); setPickerOpen(true) }}
          />
          {pickerOpen && (
            <ul className="picker-list" role="listbox" aria-label="Available cities">
              {available.length === 0 && <li className="picker-empty">No cities match your search.</li>}
              {available.map((c) => (
                <li key={c.id}>
                  <button type="button" className="picker-item" onClick={() => addCity(c.id)}>
                    <span className="picker-city">{c.name}</span>
                    <span className="picker-meta">{c.country} · {formatOffset(getOffsetMinutes(c.timeZone))}</span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>

        <fieldset className="settings">
          <legend>Awake window</legend>
          <label>
            Wake-up
            <select aria-label="Wake-up hour" value={wake} onChange={(e) => setWake(Number(e.target.value))}>
              {HOURS.map((h) => <option key={h} value={h}>{formatHour(h, format)}</option>)}
            </select>
          </label>
          <label>
            Sleep
            <select aria-label="Sleep hour" value={sleep} onChange={(e) => setSleep(Number(e.target.value))}>
              {HOURS.map((h) => <option key={h} value={h}>{formatHour(h, format)}</option>)}
            </select>
          </label>
          <div className="format-toggle" role="group" aria-label="Time format">
            <button type="button" aria-pressed={format === '12h'} className={format === '12h' ? 'fmt-btn active' : 'fmt-btn'} onClick={() => setFormat('12h')}>12h</button>
            <button type="button" aria-pressed={format === '24h'} className={format === '24h' ? 'fmt-btn active' : 'fmt-btn'} onClick={() => setFormat('24h')}>24h</button>
          </div>
        </fieldset>
      </section>

      {cities.length >= 2 && reference && (
        <section className="summary" aria-label="Overlap summary">
          {mode === 'meeting' ? (
            meetingOverlap.length === 0 ? (
              <p className="warning" role="status">⚠ No overlap — there is no hour when everyone is awake. Try widening the awake window or removing a city.</p>
            ) : (
              <div className="summary-line">
                <strong>{meetingOverlap.length} overlap {meetingOverlap.length === 1 ? 'hour' : 'hours'}</strong>
                <span className="summary-in">in {reference.name} time:</span>
                {meetingRanges.map((r) => (
                  <span key={`${r.start}-${r.end}`} className="range-badge">{formatRange(r, format)}</span>
                ))}
              </div>
            )
          ) : (
            <ul className="base-summary">
              {cities.slice(1).map((c) => {
                const hours = baseOverlap.get(c.id) ?? []
                const ranges = groupRanges(hours)
                return (
                  <li key={c.id} className="summary-line">
                    <strong>{c.name}</strong>
                    {hours.length === 0 ? (
                      <span className="warning-inline">⚠ No overlap with {reference.name}</span>
                    ) : (
                      <>
                        <span>{hours.length} overlap {hours.length === 1 ? 'hour' : 'hours'}</span>
                        <span className="summary-in">in {reference.name} time:</span>
                        {ranges.map((r) => (
                          <span key={`${r.start}-${r.end}`} className="range-badge">{formatRange(r, format)}</span>
                        ))}
                      </>
                    )}
                  </li>
                )
              })}
            </ul>
          )}
        </section>
      )}

      {cities.length < 2 && (
        <p className="warning" role="status">Add at least two cities to see an overlap.</p>
      )}

      {/* Desktop layout: cities as rows, hours as columns */}
      <div className="desktop-grid" data-layout="desktop">
        <div className="d-row d-header-row">
          <div className="d-city-col header-cell">{reference ? `Hours in ${reference.name} →` : ''}</div>
          {HOURS.map((h) => (
            <div key={h} className="d-hour header-cell">{formatHour(h, format)}</div>
          ))}
          <div className="d-action header-cell" />
        </div>
        {cities.map((city, idx) => (
          <div key={city.id} className="d-row" data-city-row={city.id}>
            <div className="d-city-col">
              <button
                type="button"
                className="city-name"
                title={idx === 0 ? 'Reference city' : `Make ${city.name} the reference city`}
                aria-label={idx === 0 ? `${city.name} (reference)` : `Make ${city.name} the reference city`}
                onClick={() => promote(city.id)}
              >
                {city.name}
              </button>
              {idx === 0 && <span className="ref-badge">REF</span>}
              <span className="city-meta">{city.country}</span>
              <span className="city-offset">{formatOffset(offsets.get(city.id) ?? 0)}</span>
            </div>
            {HOURS.map((h) => {
              const state = cellState(city, h)
              const local = localMinutes.get(city.id)?.[h] ?? 0
              return (
                <div
                  key={h}
                  className={`cell state-${state}`}
                  data-city={city.id}
                  data-ref-hour={h}
                  data-state={state}
                  title={`${city.name}: ${formatCell(local, format)} when it is ${formatHour(h, format)} in ${reference?.name}`}
                >
                  {formatCell(local, format)}
                </div>
              )
            })}
            <div className="d-action">
              <button type="button" className="remove-btn" aria-label={`Remove ${city.name}`} onClick={() => removeCity(city.id)}>×</button>
            </div>
          </div>
        ))}
      </div>

      {/* Mobile layout: cities as columns, hours as rows */}
      <div className="mobile-grid" data-layout="mobile" style={{ ['--city-count' as string]: cities.length }}>
        <div className="m-row m-header-row">
          <div className="m-hour-col header-cell">{reference?.name ?? ''}</div>
          {cities.map((city, idx) => (
            <div key={city.id} className="m-city-head">
              <button type="button" className="city-name" onClick={() => promote(city.id)} aria-label={idx === 0 ? `${city.name} (reference)` : `Make ${city.name} the reference city`}>
                {city.name}
              </button>
              {idx === 0 && <span className="ref-badge">REF</span>}
              <span className="city-offset">{formatOffset(offsets.get(city.id) ?? 0)}</span>
              <button type="button" className="remove-btn" aria-label={`Remove ${city.name}`} onClick={() => removeCity(city.id)}>×</button>
            </div>
          ))}
        </div>
        {HOURS.map((h) => (
          <div key={h} className="m-row">
            <div className="m-hour-col header-cell">{formatHour(h, format)}</div>
            {cities.map((city) => {
              const state = cellState(city, h)
              const local = localMinutes.get(city.id)?.[h] ?? 0
              return (
                <div key={city.id} className={`cell state-${state}`} data-city={city.id} data-ref-hour={h} data-state={state}>
                  {formatCell(local, format)}
                </div>
              )
            })}
          </div>
        ))}
      </div>

      <footer className="footer">
        <div className="legend">
          <span><span className="swatch state-overlap" /> Overlap</span>
          <span><span className="swatch state-awake" /> Awake</span>
          <span><span className="swatch state-sleep" /> Sleeping</span>
        </div>
        <p className="hint">
          {mode === 'meeting' ? 'Green cells = everyone awake' : `Green cells = awake at the same time as ${reference?.name ?? 'the reference city'}`}
        </p>
        <p className="hint-sub">Click a city name to make it the reference. Times use current UTC offsets, so daylight saving is handled automatically.</p>
      </footer>
    </div>
  )
}
"}

{"path":"src/styles.css","content":":root {
  --bg: #eef1ec;
  --surface: #ffffff;
  --ink: #17211a;
  --muted: #5c6b60;
  --line: #d8ded6;
  --accent: #146c3c;
  --overlap: #1a9e50;
  --overlap-ink: #ffffff;
  --awake-bg: #f2f4f0;
  --sleep-bg: #e3e7e1;
  --warn-bg: #fdf0e3;
  --warn-ink: #8a4b12;
  --warn-line: #ecc9a0;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-sans-system, "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.page { max-width: 1280px; margin: 0 auto; padding: 28px 20px 40px; }

.header {
  display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-end; justify-content: space-between;
}
h1 { margin: 0; font-size: 30px; font-weight: 800; letter-spacing: -0.02em; }
.subtitle { margin: 6px 0 0; color: var(--muted); font-size: 15px; }
.mode-help { color: var(--muted); font-size: 14px; margin: 14px 0 0; }

.mode-toggle, .format-toggle {
  display: inline-flex; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 3px; gap: 3px;
}
.mode-btn, .fmt-btn {
  border: 0; background: transparent; color: var(--muted); font: inherit; font-weight: 650; font-size: 14px;
  padding: 8px 14px; border-radius: 7px; cursor: pointer;
}
.mode-btn.active, .fmt-btn.active { background: var(--accent); color: #fff; }

.controls {
  display: flex; flex-wrap: wrap; gap: 18px; align-items: flex-start;
  background: var(--surface); border: 1px solid var(--line); border-radius: 12px;
  padding: 16px; margin: 18px 0;
}
.picker { position: relative; flex: 1 1 280px; max-width: 420px; }
.picker label, .settings label { display: block; font-size: 13px; font-weight: 700; margin-bottom: 6px; }
.picker input {
  width: 100%; font: inherit; font-size: 15px; padding: 10px 12px;
  border: 1px solid var(--line); border-radius: 8px; background: #fff; color: var(--ink);
}
.picker input:focus-visible, select:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.picker-list {
  position: absolute; z-index: 20; left: 0; right: 0; top: calc(100% + 6px);
  margin: 0; padding: 6px; list-style: none; max-height: 320px; overflow: auto;
  background: #fff; border: 1px solid var(--line); border-radius: 10px; box-shadow: 0 12px 32px rgba(20, 40, 25, 0.16);
}
.picker-item {
  display: flex; justify-content: space-between; gap: 12px; width: 100%; text-align: left;
  border: 0; background: transparent; font: inherit; padding: 9px 10px; border-radius: 7px; cursor: pointer; color: var(--ink);
}
.picker-item:hover { background: var(--awake-bg); }
.picker-city { font-weight: 650; }
.picker-meta { color: var(--muted); font-size: 13px; white-space: nowrap; }
.picker-empty { padding: 10px; color: var(--muted); font-size: 14px; }

.settings { display: flex; gap: 14px; align-items: flex-end; border: 0; margin: 0; padding: 0; }
.settings legend { font-size: 13px; font-weight: 700; padding: 0; margin-bottom: 6px; float: left; width: 100%; }
.settings select {
  font: inherit; font-size: 15px; padding: 9px 10px; border: 1px solid var(--line);
  border-radius: 8px; background: #fff; color: var(--ink);
}

.summary {
  background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; margin-bottom: 18px;
}
.summary-line { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; font-size: 15px; }
.summary-in { color: var(--muted); }
.range-badge {
  background: #e2f4e8; color: var(--accent); border: 1px solid #b5dfc2;
  font-weight: 750; font-size: 14px; padding: 4px 10px; border-radius: 999px; white-space: nowrap;
}
.base-summary { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.warning {
  background: var(--warn-bg); color: var(--warn-ink); border: 1px solid var(--warn-line);
  border-radius: 10px; padding: 12px 14px; font-size: 15px; margin: 0 0 18px;
}
.summary .warning { margin: 0; }
.warning-inline { color: var(--warn-ink); font-weight: 650; }

/* --- Desktop grid --- */
.desktop-grid { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 12px; overflow-x: auto; }
.d-row {
  display: grid; gap: 3px; align-items: stretch; min-width: 980px;
  grid-template-columns: 190px repeat(24, minmax(30px, 1fr)) 34px;
  margin-bottom: 6px;
}
.d-row:last-child { margin-bottom: 0; }
.header-cell { font-size: 11px; font-weight: 700; color: var(--muted); display: flex; align-items: center; justify-content: center; text-align: center; }
.d-city-col.header-cell { justify-content: flex-start; font-size: 12px; }
.d-city-col { display: flex; flex-wrap: wrap; align-items: center; gap: 5px 7px; padding-right: 8px; }
.city-name {
  border: 0; background: transparent; font: inherit; font-weight: 750; font-size: 15px; color: var(--ink);
  cursor: pointer; padding: 2px 0; text-align: left;
}
.city-name:hover { text-decoration: underline; }
.ref-badge {
  background: var(--accent); color: #fff; font-size: 10px; font-weight: 800; letter-spacing: 0.06em;
  padding: 2px 6px; border-radius: 4px;
}
.city-meta { color: var(--muted); font-size: 12px; width: 100%; order: 3; }
.city-offset { color: var(--muted); font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums; }
.d-action { display: flex; align-items: center; justify-content: center; }
.remove-btn {
  border: 1px solid var(--line); background: #fff; color: var(--muted); width: 26px; height: 26px;
  border-radius: 7px; font-size: 16px; line-height: 1; cursor: pointer; padding: 0;
}
.remove-btn:hover { color: #a12626; border-color: #e2b3b3; background: #fdf1f1; }

.cell {
  display: flex; align-items: center; justify-content: center; min-height: 38px;
  border-radius: 6px; font-size: 12px; font-variant-numeric: tabular-nums; padding: 2px 1px; text-align: center;
}
.state-sleep { background: var(--sleep-bg); color: #93a196; opacity: 0.75; }
.state-awake { background: var(--awake-bg); color: var(--ink); border: 1px solid var(--line); }
.state-overlap { background: var(--overlap); color: var(--overlap-ink); font-weight: 800; }

/* --- Mobile grid --- */
.mobile-grid { display: none; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 10px; overflow-x: auto; }
.m-row {
  display: grid; gap: 3px; margin-bottom: 3px;
  grid-template-columns: 58px repeat(var(--city-count, 1), minmax(62px, 1fr));
}
.m-hour-col { justify-content: flex-start; }
.m-city-head { display: flex; flex-direction: column; align-items: center; gap: 3px; text-align: center; padding: 4px 2px; }
.m-city-head .city-name { font-size: 13px; text-align: center; }

.footer { margin-top: 18px; }
.legend { display: flex; flex-wrap: wrap; gap: 16px; font-size: 13px; color: var(--muted); }
.legend > span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 16px; height: 16px; border-radius: 4px; display: inline-block; }
.hint { font-weight: 750; font-size: 15px; margin: 14px 0 4px; }
.hint-sub { color: var(--muted); font-size: 13px; margin: 0; }

@media (max-width: 767px) {
  .page { padding: 20px 12px 32px; }
  h1 { font-size: 24px; }
  .desktop-grid { display: none; }
  .mobile-grid { display: block; }
  .cell { min-height: 30px; font-size: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
