{"path":"/tmp/tz-probe2.js","content":"const page = await browser.getPage("tz-check");
await page.setViewportSize({ width: 1280, height: 900 });
await page.goto("http://localhost:9300/");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".desktop-grid");
// overnight: wake 22, sleep 6 ; SF row awake cells should be 22,23,0..5
await page.selectOption('select[aria-label="Wake-up hour"]', "22");
await page.selectOption('select[aria-label="Sleep hour"]', "6");
const overnight = await page.evaluate(() => {
  const cells = [...document.querySelectorAll('[data-city-row="san-francisco"] .cell')];
  return {
    awakeHours: cells.filter(c => c.getAttribute("data-state") !== "sleep").map(c => c.getAttribute("data-ref-hour")),
    summary: document.querySelector(".summary")?.textContent?.replace(/\s+/g, " ").trim(),
  };
});
console.log("OVERNIGHT:", JSON.stringify(overnight));
// reset, add Kathmandu for :45 fractional cells
await page.selectOption('select[aria-label="Wake-up hour"]', "7");
await page.selectOption('select[aria-label="Sleep hour"]', "23");
await page.fill("#city-search", "Nepal");
await page.click('.picker-item:has-text("Kathmandu")');
const frac = await page.evaluate(() => {
  const cells = [...document.querySelectorAll('[data-city-row="kathmandu"] .cell')];
  return { sample: cells.slice(0, 4).map(c => c.textContent), offset: document.querySelector('[data-city-row="kathmandu"] .city-offset')?.textContent };
});
console.log("FRACTIONAL:", JSON.stringify(frac));
// catalog size via picker after removing added city search empty: count items when cleared to defaults
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".desktop-grid");
await page.click("#city-search");
const catalog = await page.evaluate(() => ({
  available: document.querySelectorAll(".picker-item").length,
  defaults: document.querySelectorAll("[data-city-row]").length,
}));
console.log("CATALOG:", JSON.stringify(catalog), "total =", catalog.available + catalog.defaults);
const shot = await saveScreenshot(await page.screenshot(), "tz-default.png");
console.log("SCREENSHOT:", shot);
"}

